-- V90.da: Advanced Production Scheduling Optimization
CREATE TABLE IF NOT EXISTS manufacturing_routing (routing_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, product_id TEXT NOT NULL, version_code TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,product_id,version_code));
CREATE TABLE IF NOT EXISTS manufacturing_routing_operation (operation_id TEXT PRIMARY KEY, routing_id TEXT NOT NULL, sequence_no INTEGER NOT NULL, operation_code TEXT NOT NULL, operation_name TEXT NOT NULL, work_center_id TEXT NOT NULL, setup_hours NUMERIC NOT NULL DEFAULT 0, run_hours_per_unit NUMERIC NOT NULL DEFAULT 0, priority INTEGER NOT NULL DEFAULT 100, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(routing_id,sequence_no));
CREATE TABLE IF NOT EXISTS manufacturing_work_center_compatibility (compatibility_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, product_id TEXT NOT NULL, work_center_id TEXT NOT NULL, setup_hours NUMERIC NOT NULL DEFAULT 0, run_hours_per_unit NUMERIC NOT NULL DEFAULT 0, efficiency_pct NUMERIC NOT NULL DEFAULT 100, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(organization_id,entity_id,product_id,work_center_id));
CREATE TABLE IF NOT EXISTS manufacturing_optimized_schedule (optimized_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, production_order_id TEXT NOT NULL, product_id TEXT NOT NULL, operation_id TEXT NOT NULL, work_center_id TEXT NOT NULL, sequence_no INTEGER NOT NULL, scheduled_date DATE NOT NULL, shift_code TEXT NOT NULL, planned_qty NUMERIC NOT NULL DEFAULT 0, setup_hours NUMERIC NOT NULL DEFAULT 0, run_hours NUMERIC NOT NULL DEFAULT 0, total_hours NUMERIC NOT NULL DEFAULT 0, priority INTEGER NOT NULL DEFAULT 100, due_date DATE, status TEXT NOT NULL DEFAULT 'PROPOSED', created_by TEXT NOT NULL, approved_by TEXT, approved_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS manufacturing_optimization_exception (exception_id TEXT PRIMARY KEY, optimized_id TEXT NOT NULL, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, exception_type TEXT NOT NULL, message TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'WARNING', status TEXT NOT NULL DEFAULT 'OPEN', resolved_by TEXT, resolved_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_mfg_opt_scope ON manufacturing_optimized_schedule(organization_id,entity_id,scheduled_date,work_center_id,status);
